/* ══════════════════════════════════════════════════════════
   실내 여섯 — 건물마다 한 방씩.

   **이 파일의 규칙 하나: 통로가 먼저다.**
   전 판은 예쁜 스크린샷을 기준으로 가구를 놓았습니다. 그 결과 방마다
   걸을 수 있는 바닥이 7~26% 뿐이었고, 문 앞 시작 자리가 여섯 중 넷에서
   가구 안에 박혀 있어서 **아예 한 발짝도 못 움직였습니다.** 말 걸 자리는
   한 곳도 못 닿았습니다.

   그래서 방마다 CORRIDORS 를 먼저 적고, 가구는 그 바깥에만 놓습니다.
   diagroom.html 이 침범한 가구를 이름으로 집어 주고, 문에서 물을 채워
   모든 자리에 닿는지 검사합니다. 통로 폭은 전부 2.0 이상입니다.

   **방 안에 장식용 사람을 두지 않습니다.** 전 판은 방마다 서너 명을
   세워 놨는데, 말도 안 걸리고 비켜 주지도 않아서 마네킹이었습니다.
   지금은 말 걸 수 있는 NPC 만 npcs.js 의 INDOOR 로 세웁니다.
   ══════════════════════════════════════════════════════════ */
import * as THREE from 'three';
import { M, box, cyl, prism } from './parts.js';
import * as R from './room.js';

const IN = R.IN;

/* 방 크기 — 전 판보다 한 단계씩 키웠습니다. 같은 가구를 넣어도
   통로가 남아야 방이고, 안 남으면 창고입니다. */
/* 도서관과 본관을 한 단계 더 키웁니다.

   픽셀맵의 열람실은 **책상이 줄줄이 늘어서고 그 사이가 넉넉한** 방
   이었습니다. 3D 로 옮기면서 26×18 로 줄었더니 탁자가 둘뿐이라
   "도서관에 온 느낌" 이 아니라 "책상 있는 방" 이 됐습니다.

   40×28 이면 긴 탁자 여섯 줄에 마흔여덟 자리가 들어가고, 그러고도
   통로가 남습니다. 천장도 5.0 에서 6.4 로 — 열람실은 높아야 조용해
   보입니다(소리가 아니라 눈이 그렇게 읽습니다).

   본관 강의실도 같은 이유로 34×24. 줄이 셋에서 다섯이 됩니다. */
/* 한 번 더 키웁니다. 40×28 도 걸어 보면 금세 끝납니다 — 픽셀맵의
   열람실은 **끝이 안 보이는** 깊이가 있었고, 그 깊이가 "쾌적함" 의
   정체였습니다. 48×34 면 탁자 여덟 줄이 들어가고도 통로가 남습니다.
   본관도 같은 비율로 40×28. */
export const ROOM_SIZE = {
  library:  { w: 48, d: 34, h: 7.0 },
  mainhall: { w: 40, d: 28, h: 5.8 },
  dorm:     { w: 14, d: 11, h: 4.2 },
  union:    { w: 26, d: 18, h: 4.8 },
  arcade:   { w: 20, d: 14, h: 4.6 },
  shop:     { w: 24, d: 17, h: 5.0 },
};

/* 비워 두어야 하는 곳 [x0, z0, x1, z1]. 가구가 여기 걸치면 검사에서 걸립니다. */
export const CORRIDORS = {
  library:  [[-3.0, -16.0, 3.0, 16.4], [-23.4, 5.4, 23.4, 8.2], [-23.4, -6.2, 23.4, -3.4],
             [18.6, -15.0, 22.4, 15.0], [-22.4, -15.0, -18.6, 15.0]],
  mainhall: [[-3.0, -13.4, 3.0, 13.6], [-19, 6.6, 19, 8.8], [-19, -5.0, 19, -2.6]],
  dorm:     [[-1.7, -4.6, 1.7, 5.4], [-7, 0.4, 7, 2.2]],
  union:    [[-3.0, -8.0, 3.0, 8.7], [-12.4, 2.0, 12.4, 3.6], [-12.4, -5.4, 12.4, -3.8]],
  arcade:   [[-2.4, -6.0, 2.4, 6.8], [-10, 0.6, 10, 2.6]],
  shop:     [[-2.6, -7.4, 2.6, 8.1], [-11.4, 0.4, 11.4, 2.5]],
};

export const ROOMS = {
  /* ══ ① 도서관 ══ 22×16. 앉아서 오래 버티는 방.
     세로 통로 하나 · 가로 통로 하나 · 서가 앞 통로 하나. */
  library(g) {
    /* ══ ① 도서관 ══ 40×28 — 열람실.
       세로 통로 하나 · 가로 통로 둘 · 창가 통로 둘. 탁자는 그 사이에만. */
    R.doormat(g, 0, 16.2);
    R.exitSign(g, 0, 16.72, 0x2C8C7E);
    R.shell(g, 48, 34, 7.0, { floorA: 0xD9E5E4, floorB: 0xC3D5D4, wall: 0xF4F8F7 });
    [-19, -14, -9, 9, 14, 19].forEach((x) => R.window3(g, x, 3.6, 34, 2.3, 3.0));

    /* ── 뒤벽 서가 ── 좁은 책장 스물한 개가 서로 파고들던 벽을
       폭 넓은 아홉 칸의 갤러리 서가로 다시 짭니다. 가운데 두 칸은 낮춰
       반복을 끊고, 양옆은 대칭으로 정렬해 한 덩어리로 읽힙니다. */
    [-19.2, -14.4, -9.6, -4.8, 0, 4.8, 9.6, 14.4, 19.2].forEach((x, i) =>
      R.shelf(g, x, -16.28, 0, i === 4 ? 3.5 : 4.15, i === 4 ? 3.7 : 4.65));
    /* 좌우 벽도 창마다 하나씩만 — 같은 자리에 두 개씩 겹치지 않습니다. */
    [-12.6, 12.6].forEach((z) => {
      R.shelf(g, -22.9, z, Math.PI / 2, 1.9, 4.0);
      R.shelf(g, 22.9, z, -Math.PI / 2, 1.9, 4.0);
    });
    /* 방 가운데는 앞뒤로 겹친 두 줄을 삭제하고 독립 아일랜드 둘만 둡니다. */
    [-9.2, 9.2].forEach((cx) => R.shelf(g, cx, -10.6, 0, 4.2, 3.8));

    /* ── 가운데 서가 두 열 ──
       세로 통로(x ±3)와 열람 탁자(x ±10 부터) 사이의 폭 7짜리 띠가
       통째로 맨바닥이었습니다. 물건 167개로 바닥의 40%를 덮으면서도
       **한가운데는 10%** 였고, 걸어 보면 방을 대각선으로 가로지르는
       빈 길이 생깁니다.

       도서관의 가운데는 원래 서가입니다. 벽에만 책을 붙여 두면
       열람실이 아니라 강당이 됩니다. 가로 통로(z 5.4~8.2, -6.2~-3.4)
       는 그대로 비우고 그 사이 구간에만 세웁니다.

       높이를 3.4 와 4.0 으로 번갈아 둡니다 — 다 같은 높이면 벽이 되고,
       벽이 되면 안쪽 열람석이 안 보여서 방이 도로 작아집니다.

       서가는 **등을 맞대어 두 장씩** 세웁니다. 한 장만 세우면 반대편에서
       볼 때 민무늬 갈색 판이라, 방 한가운데에 빈 광고판이 다섯 개 서
       있는 것처럼 보였습니다. 실제 서가도 양면입니다. */
    const STACK = [-15.2, -12.6, -10.0, -7.4, -1.8, 0.8, 3.4, 9.8, 12.4];
    STACK.forEach((z, i) => {
      const h = i % 2 ? 3.4 : 4.0;
      R.shelf(g, -6.66, z, -Math.PI / 2, 2.3, h);   // 통로 쪽 면
      R.shelf(g, -6.14, z, Math.PI / 2, 2.3, h);    // 열람석 쪽 면
      /* +x 쪽 z 12.4 는 반납 책수레(5.0·6.6, 12.2) 자리라 건너뜁니다 */
      if (z < 11) {
        R.shelf(g, 6.14, z, -Math.PI / 2, 2.3, h);
        R.shelf(g, 6.66, z, Math.PI / 2, 2.3, h);
      }
    });
    /* 서가 열 끝에 안내판 — 어느 열인지 모르면 서가는 그냥 벽입니다.
       가로 통로(z -6.2~-3.4)를 물지 않게 앞쪽 열 끝에 둡니다. */
    R.aFrame(g, -6.4, 5.0, 0, 0x2C8C7E);
    R.aFrame(g, 6.4, 5.0, Math.PI, 0x63C47C);

    /* 레퍼런스의 계단형 열람 라운지. 기능 책수레(4.6,13.6), 중앙 통로,
       창가 캐럴을 모두 피한 뒤쪽 양 코너에만 둡니다. 낮은 단과 쿠션이라
       시야를 막지 않고, 기존 기능 구역으로 오인할 별도 E 존도 없습니다. */
    [-15.0, 15.0].forEach((cx, side) => {
      const warm = side ? 0x9FC7B4 : 0xD7A68B;
      box(g, 6.2, .24, 3.0, .10, M(0xE9DCC7, .76), cx, .14, -11.2);
      box(g, 6.2, .24, 1.35, .10, M(0xD9C7AA, .75), cx, .38, -11.95);
      [-2.0, 0, 2.0].forEach((dx, i) => {
        box(g, 1.35, .16, .78, .12, M(i % 2 ? 0x7FA8C4 : warm, .64), cx + dx, .56, -11.95);
        R.lowTable(g, cx + dx, -9.95, 0, .72, .62);
      });
    });

    /* ── 열람 탁자 여섯 ── 두 줄 × 셋. 여덟 자리씩 마흔여덟.
       세로 통로(x ±2.6)를 비켜 좌우로 갈라 놓습니다. */
    [[-13.4, -5.4], [-13.4, 1.6], [-13.4, 8.6],
     [13.4, -5.4], [13.4, 1.6], [13.4, 8.6]].forEach(([cx, cz], k) => {
      R.readTable(g, cx, cz, 0, 6.8);
      [-2.4, -1.2, 0, 1.2, 2.4].forEach((t) => {
        R.chair(g, cx + t * 1.15, cz - 1.5, 0, k % 2 ? IN.wood : IN.woodLight);
        R.chair(g, cx + t * 1.15, cz + 1.5, Math.PI, k % 2 ? IN.woodLight : IN.wood);
      });
      /* 등 — 탁자마다 둘. 랜딩 그림에서 이 청록 갓들이 열람실을
         열람실로 만들던 것입니다. */
      R.lamp(g, cx - 2.2, .87, cz);
      R.lamp(g, cx + 2.2, .87, cz);
      R.books(g, cx - 1.1, .87, cz + (k % 2 ? .45 : -.45), 3);
      R.books(g, cx + 1.6, .87, cz - (k % 2 ? .45 : -.45), 2);
      R.laptop(g, cx + .4, .87, cz - .55, Math.PI);
      if (k % 2 === 0) R.laptop(g, cx - 1.7, .87, cz + .55, 0);
      if (k % 3 === 1) R.deskClutter(g, cx + 2.6, .87, cz + .2);
    });

    /* ── 1인 캐럴 ── 창가 두 줄. 오래 앉는 자리입니다. */
    [-13.0, -9.6, -6.2, -2.8, 2.8, 6.2, 9.6, 13.0].forEach((z) => {
      R.carrel(g, -20.4, z, -Math.PI / 2);
      R.chair(g, -19.4, z, -Math.PI / 2, IN.woodLight);
      R.carrel(g, 20.4, z, Math.PI / 2);
      R.chair(g, 19.4, z, Math.PI / 2, IN.woodLight);
    });

    /* ── 앞쪽 ── 대출대와 쉬는 자리 */
    R.counter(g, -8.0, 14.4, Math.PI, 6.4, IN.woodDark);
    R.counterTop(g, -8.0, 1.1, 14.2);
    /* 지구본은 대출대 상판 안쪽에 올립니다. 이전 x=-4.4 는 상판 끝을
       벗어나 바닥 장식처럼 보였습니다. */
    R.globe(g, -10.2, 1.08, 14.2);
    /* 반납 책수레 둘은 출입문 축(x ±3)을 비우고 같은 방향으로 나란히.
       책 정리 미니게임 반경도 spots.js 에서 이 두 수레 사이로 옮깁니다. */
    R.bookCart(g, 5.0, 12.2, 0);
    R.bookCart(g, 6.6, 12.2, 0);
    R.sofa(g, 8.4, 15.2, Math.PI, 4.2, 0x7FA8C4);
    R.lowTable(g, 8.4, 13.4, 0, 2.2, 1.2);
    R.books(g, 8.1, .56, 13.4, 2);

    /* ── 벽 · 천장 ── */
    R.clock(g, 14.0, 5.0, -16.82);
    R.poster(g, -23.72, 3.8, -8.0, Math.PI / 2, 1.1, 1.4, 0x63C47C);
    R.poster(g, -23.72, 3.8, 5.0, Math.PI / 2, 1.1, 1.4, 0xE8935A);
    R.poster(g, -8.0, 3.9, -16.82, 0, 1.2, 1.5, 0x5B84C4);
    R.banner(g, -23.72, 5.0, -1.0, Math.PI / 2, 4.4, 1.2, 0x2C8C7E);
    [-13.4, 0, 13.4].forEach((x) => [-5.4, 1.6, 8.6, 13.4].forEach((z) => R.pendant(g, x, z, 6.58)));
    R.rug(g, 8.4, 14.0, 7.4, 4.2, 0xB08AB0, 0xF2E4E8);
  },

  /* ══ ② 본관 ══ 34×24. 대형 강의실.

     22×16 에 두 줄 × 세 칸이면 스물넷 자리라 세미나실이었습니다.
     본관 강의실은 층계식 대형 강의실이고, 픽셀맵의 체감도 그쪽이었습니다.
     34×24 로 넓혀 다섯 줄 × 두 칸 — 여든 자리. 줄 사이는 그대로 넉넉히. */
  mainhall(g) {
    R.doormat(g, 0, 13.2);
    R.exitSign(g, 0, 13.72, 0x3F6BA8);

    R.shell(g, 40, 28, 5.8, { floorA: 0xE8E2D2, floorB: 0xD6CFBC, wall: 0xE6EAF2, under: 0x8A9098 });
    R.blackboard(g, -4.0, 2.7, -13.7, 13.0, 3.1);
    R.projScreen(g, 9.0, 3.1, -13.78, 5.0, 2.9);
    [-15.0, -9.0, 9.0, 15.0].forEach((x) => R.window3(g, x, 3.1, 28, 2.3, 2.5));

    /* 교탁 구역 — 세로 통로를 비켜 양옆으로 */
    R.podium(g, -9.4, -11.8, .18);
    R.desk(g, 7.6, -11.8, 0, 3.2, 1.1, .9);
    R.books(g, 6.8, 1.06, -11.8, 2);
    R.laptop(g, 8.5, 1.06, -11.8);

    /* ── 강의석 여섯 줄 × 두 칸 ──
       전 판은 폭 8.4 짜리 책상을 x ±12.4 에 놨습니다. 그러면 좌석은
       x 8.2 부터 시작하고, 세로 통로가 끝나는 x 3 과의 사이에 **폭 5의
       죽은 띠**가 남습니다. 걸어 보면 강의실 한복판이 빈 복도예요.

       책상을 폭 11.0 으로 늘리고 x ±10.9 로 당깁니다 — 좌석이 x 5.4
       부터 시작해 통로 옆까지 이어지고, 한 줄이 여섯에서 여덟으로
       늘어 96석이 됩니다. 세로 통로 폭(x -3~3)은 그대로입니다. */
    [-7.6, -4.2, -.8, 2.6, 6.0, 9.4].forEach((z, ri) => {
      [-10.9, 10.9].forEach((x, ci) => {
        R.desk(g, x, z, 0, 11.0, 1.2, .78);
        [-4.6, -3.3, -2.0, -0.7, 0.6, 1.9, 3.2, 4.5].forEach((dx) =>
          R.chair(g, x + dx, z + 1.3, Math.PI, ci ? 0x9BB4D6 : 0x8FC4B4));
        /* 책상이 8.4 에서 11.0 으로 넓어졌으니 위에 올린 것도 같이
           벌립니다 — 안 벌리면 넓힌 만큼 양끝이 다시 빈 상판입니다. */
        R.books(g, x - 4.2, .87, z - .1, 2);
        R.books(g, x + 4.0, .87, z + .1, ((ri + ci) % 2) + 1);
        if ((ri + ci) % 2 === 0) R.laptop(g, x + 1.4, .87, z - .1);
        if ((ri + ci) % 3 === 1) R.deskClutter(g, x - 1.4, .87, z);
        if ((ri + ci) % 4 === 2) R.books(g, x + .2, .87, z + .3, 1);
        if ((ri + ci) % 3 === 2) R.laptop(g, x - 2.6, .87, z + .3, Math.PI);
      });
    });

    /* ── 앞쪽 ── 사물함 · 벤치 · 식물 */
    R.lockers(g, -19.4, -3.0, Math.PI / 2, 6, 0x8AB4CE);
    R.lockers(g, 19.4, -3.0, -Math.PI / 2, 6, 0xCEAF8A);
    R.bench(g, -15.0, 13.0, 0, 3.6);
    R.bench(g, 15.0, 13.0, 0, 3.6);
    R.plant(g, 19.2, 12.6, 1.15);
    R.plant(g, -19.2, 12.6, 1.0);
    R.bin(g, -5.0, 13.4); R.bin(g, 4.8, -10.4);

    /* ── 벽 · 천장 ── */
    R.clock(g, 14.0, 4.2, -13.82);
    R.poster(g, -19.72, 3.3, -5.0, Math.PI / 2, 1.1, 1.4, 0x5B84C4);
    R.poster(g, 19.72, 3.3, 5.0, -Math.PI / 2, 1.1, 1.4, 0xE8935A);
    R.banner(g, -19.72, 4.4, 5.6, Math.PI / 2, 3.8, 1.1, 0x3F6BA8);
    [-12.4, 0, 12.4].forEach((x) => [-7.6, -.8, 6.0].forEach((z) => R.pendant(g, x, z, 5.12)));
    R.rug(g, 0, -11.2, 9.6, 3.8, 0xA8B8D0, 0xEEF2F8);
    R.aFrame(g, -17.0, 9.0, .5, 0x3F6BA8);
  },

  /* ══ ③ 기숙사 ══ 14×11. 내 방. 좁아도 침대·책상·옷장 사이는 다녀야 합니다. */
  dorm(g, decor) {
    R.doormat(g, 0, 4.75, 0xC98E4E);
    R.exitSign(g, 0, 5.27, 0xC98E4E);
    /* 내가 놓은 가구 — 상점에서 사서 방 꾸미기로 놓은 것들 */
    (decor || []).forEach((d) => decorItem(g, d));

    R.shell(g, 14, 11, 4.2, { floorA: 0xDDE7E5, floorB: 0xC8D8D5, wall: 0xF6FAF8 });
    R.window3(g, 3.0, 2.5, 11, 2.4, 2.1);
    R.window3(g, -3.4, 2.5, 11, 2.0, 2.1);

    R.bed(g, -4.9, -3.1, 0);
    R.desk(g, 4.6, -1.7, 0, 2.8, 1.1, .78);
    R.chair(g, 4.6, -0.6, 0, IN.wood);
    R.laptop(g, 4.6, .87, -1.6, Math.PI);
    R.lamp(g, 5.8, .87, -1.6);
    R.books(g, 3.5, .87, -1.6, 3);
    R.deskClutter(g, 4.0, .87, -2.1);
    R.shelf(g, -6.6, 3.4, Math.PI / 2, 1.7, 2.0);
    /* 옷장 — 이 방의 개념이 "내 방 · 침대와 옷장" 인데 정작 옷장이
       없었습니다. room.js 에 wardrobe 가 만들어져 있는데도 여섯 방
       어디서도 안 부르고 있었어요. 침대 머리맡 벽에 붙입니다. */
    /* 뒷벽 창 둘이 x 3.0 과 -3.4 라 그 사이에는 못 넣습니다 —
       처음 놓은 -2.9 는 왼쪽 창을 반쯤 가렸습니다. 책상 뒤 코너로. */
    R.wardrobe(g, 5.6, -4.6, 0);
    R.fridge(g, 6.2, 3.6, -.5);
    R.coffee(g, 6.2, 1.28, 3.6);
    R.laundry(g, -6.2, 4.6);
    R.guitar(g, -6.3, 1.2, .3);
    /* 옷 갈아입기 구역을 걷고, 출입문 옆에 안내 표지판 하나를 둡니다.
       Deskfit 사용법과 카메라 개인정보는 이 판의 탭 둘에서 함께 봅니다. */
    R.infoKiosk(g, -4.7, 3.8, .35, 0x2DD4BF);
    [[-5.0, 3.0, 0xE8935A], [-2.4, 4.6, 0x63C47C]].forEach(([cx, cz, c]) => {
      box(g, 1.0, .24, 1.0, .11, M(c, .82), cx, .22, cz).castShadow = true;
      box(g, .78, .1, .78, .08, M(c, .68), cx, .35, cz);
    });
    R.bin(g, 2.6, 4.8, 0xE8935A);
    /* 창 두 장은 날씨를 보는 면이라 선반·전구·게시물을 모두 걷습니다.
       게시물은 왼쪽 벽으로 옮겨 창틀과 깊이가 겹치지 않게 합니다. */
    R.board(g, -6.82, 2.7, -1.8, 1.8, 1.2, Math.PI / 2);
    R.poster(g, -6.82, 2.9, 1.2, Math.PI / 2, .9, 1.2, 0xE8695A);
    R.poster(g, -6.82, 2.7, 3.2, Math.PI / 2, .9, 1.2, 0xF2C14E);
    R.clock(g, 5.9, 3.35, -5.32, 0, .30);
    R.pendant(g, 0, 0, 3.78, 0xE8C08A);
    R.rug(g, 0, -1.4, 4.2, 3.2, 0x4E8C9E, 0xEAF2F4);
    /* 창가 화분은 유리 안에 초록 얼룩처럼 겹쳐 보여 앞쪽 왼편으로 이동. */
    R.plant(g, -5.8, 2.1, .9);
    /* 기능 반경과 중앙 통로 밖의 빈 코너. 장식이 아니라 실제 앉기 좌석입니다. */
    R.beanbag(g, 3.1, 3.1, -.45, 0x8CAFC8);
    R.lowTable(g, 4.25, 3.35, 0, .72, .62);

  },

  /* ══ ④ 학생회관 ══ 22×15. 창구 · 식당 · 라운지가 한 층에. */
  union(g) {
    R.doormat(g, 0, 8.0, 0x43A05C);
    R.exitSign(g, 0, 8.52, 0x43A05C);

    R.shell(g, 26, 18, 4.8, { floorA: 0xEDF2EE, floorB: 0xDEE9E5, wall: 0xF5FAF8, under: 0x8A9AA0 });
    R.window3(g, -8.3, 2.8, 18, 2.4, 2.2);
    R.window3(g, 0, 2.8, 18, 2.4, 2.2);
    /* 오른쪽 벽은 학생식당 메뉴판이 씁니다. 같은 자리에 있던 창을
       지워 메뉴 카드·시계·창틀이 한 덩어리로 겹쳐 보이지 않게 합니다. */

    /* 명예의 전당 — 학생증 책상과 완전히 분리한 왼쪽 벽 갤러리입니다.
       검은 판 하나 대신 학교 상징·상위 세 명·기록 선반이 밝은 클레이
       액자 안에 들어갑니다. 출구 정면과 식당 동선도 침범하지 않습니다. */
    { const hall = new THREE.Group(); hall.position.set(-12.72, 0, -1.4); hall.rotation.y = Math.PI / 2; g.add(hall);
      box(hall, 7.4, 3.35, .20, .16, M(0xDDEAF4, .66), 0, 2.45, 0);
      box(hall, 6.9, 2.86, .16, .14, M(0xF8FCFF, .72), 0, 2.42, .13);
      box(hall, 4.4, .34, .18, .14, M(0x8FCFC6, .62), 0, 3.66, .24);
      /* 중앙 학교 문장 — 월계수형 두 링과 학교색 코어. */
      cyl(hall, .48, .48, .10, 28, M(0xD9B95B, .48), 0, 2.92, .28).rotation.x = Math.PI / 2;
      cyl(hall, .35, .35, .11, 24, M(0x4FAFA4, .58), 0, 2.92, .34).rotation.x = Math.PI / 2;
      box(hall, 1.7, .12, .13, .04, M(0xA4B7C8, .42), 0, 2.30, .32);
      [-2.35, 0, 2.35].forEach((x, i) => {
        const c = [0xAFC3D5, 0xD9B95B, 0xC98A68][i];
        box(hall, 1.52, 1.68, .16, .12, M(0xD7E4EF, .58), x, 2.43, .28);
        box(hall, 1.30, 1.45, .12, .10, M(0xFFFFFF, .7), x, 2.43, .39);
        cyl(hall, .26, .27, .08, 20, M(c, .58), x, 2.72, .48).rotation.x = Math.PI / 2;
        box(hall, .72, .10, .10, .04, M(0x526A7C, .36), x, 2.28, .48);
        box(hall, .50, .07, .10, .03, M(0x90A5B5, .34), x, 2.08, .48);
      });
      box(hall, 6.2, .18, .34, .07, M(0xB8C8D5, .5), 0, 1.42, .20);
      [-2.4, -1.2, 0, 1.2, 2.4].forEach((x, i) =>
        cyl(hall, .10, .13, .22 + (i % 2) * .08, 14, M([0x7FA8C4,0x63C47C,0xF2C14E][i % 3], .48), x, 1.64, .28));
    }

    /* 왼쪽 두 번째 책상은 학생증 발급 전용. 책상 위 카드 모형도 같이 둡니다. */
    R.counter(g, -5.2, -7.0, 0, 3.4, IN.woodDark);
    R.counterTop(g, -5.2, 1.1, -6.8);
    R.chair(g, -5.2, -8.0, 0, 0x9BB4D6);
    R.board(g, -5.2, 3.1, -8.82, 2.6, 1.6);
    box(g, .76, .48, .06, .06, M(0xDCEAF5, .5), -5.2, 1.28, -6.52);
    box(g, .20, .20, .07, .05, M(0x2DD4BF, .5), -5.42, 1.32, -6.47);
    [0, 1, 2].forEach((i) => box(g, .30 - i * .04, .04, .07, .02,
      M(0x526174, .4), -4.98, 1.40 - i * .09, -6.47));

    /* 학생식당 — 배식 레일·메뉴보드·식판·대기줄이 한 덩어리로 보입니다. */
    R.trayCounter(g, 6.6, -7.0, 0, 5.8);
    /* 칠판 대신 메뉴 카드와 식기 선반 — 강의실처럼 보이던 요소를 제거합니다. */
    box(g, 5.8, 1.38, .16, .14, M(0xFFF8EA, .68), 6.6, 3.05, -8.80);
    [4.75, 6.6, 8.45].forEach((x, i) => {
      box(g, 1.45, .92, .12, .10, M([0xF8D6C8,0xD8EEE7,0xDCE8F5][i], .62), x, 3.05, -8.67);
      cyl(g, .18, .18, .06, 18, M([0xE8935A,0x63C47C,0x7FA8C4][i], .48), x, 3.20, -8.57).rotation.x = Math.PI / 2;
      box(g, .72, .07, .08, .03, M(0x667789, .36), x, 2.88, -8.55);
    });
    [-1.8, -.6, .6, 1.8].forEach((dx, i) => {
      box(g, .72, .05, .48, .04, M(0xB9C7D4, .42), 6.4 + dx, 1.46, -5.18);
      [0, 1, 2].forEach((k) => cyl(g, .10 + k * .025, .10 + k * .025, .04,
        12, M([0xF3F0DF, 0xD98562, 0x6BAA78][(i + k) % 3], .45),
        6.14 + dx + k * .22, 1.51, -5.10));
    });
    /* 식탁은 벽과 출구에서 안쪽으로 당기고 중앙 출입 통로는 비웁니다. */
    /* 식탁은 오른쪽 식당 구역에 두 벌만 둡니다. 왼쪽 두 벌이 라운지
       소파·낮은 책상과 겹쳐 의자 사이를 걸을 수 없었습니다. */
    /* 식탁 둘이면 배식대만 있고 식당은 없습니다 — 오른쪽 구역을
       다섯 벌로 채웁니다. 가로 통로(z 2~3.6, -5.4~-3.8)는 비웁니다. */
    [[8.2, .8, 0xF2C14E], [8.2, 5.2, 0xE8935A], [4.9, -1.4, 0x63C47C],
     [10.6, -1.9, 0x7FA8C4], [5.2, 5.6, 0x9B7BD4]]
      .forEach(([x, z, c]) => R.cafeSet(g, x, z, c));

    /* 라운지 — 앞쪽 가운데 양옆 */
    /* 탁자가 가운데 있으므로 소파 둘은 **서로 마주** 봅니다.
       전 판은 둘 다 ry 0 이라 탁자를 옆에 두고 바깥을 봤습니다. */
    R.sofa(g, -7.8, 3.4, Math.PI, 2.8, 0x9B7BD4);
    R.lowTable(g, -7.8, 2.0, 0, 2.0, 1.0);
    R.books(g, -8.1, .56, 2.0, 2);

    /* ── 동아리 모집 부스 세 칸 ──
       왼쪽 가운데 8.6×5.4 가 통째로 맨바닥이었습니다. 26×18 방에
       물건이 26개뿐이라 **가운데를 덮은 비율이 3%** 였고, 벽을 따라
       한 바퀴 돌면 그게 방의 전부였습니다.

       학생회관 복도에 늘 있는 것을 그 자리에 둡니다. 명예의 전당
       (x -12.7)과 세로 통로(x -3~3) 사이, 가로 통로 둘의 사이입니다. */
    [[-10.8, 0x63C47C], [-7.8, 0xF2C14E], [-4.8, 0x7FA8C4]].forEach(([x, c], i) => {
      R.desk(g, x, -1.2, 0, 2.4, .9, .74);
      R.chair(g, x, -2.4, 0, 0x9BB4D6);
      R.books(g, x - .7, .82, -1.2, 2 - (i % 2));
      if (i % 2 === 0) R.laptop(g, x + .6, .82, -1.2, Math.PI);
      else R.deskClutter(g, x + .6, .82, -1.2);
      /* 안내판은 부스 **사이**에 세웁니다. x+1.5 로 두면 마지막 칸의
         것이 세로 통로(x -3~3)를 물어서 검사에 걸렸습니다. */
      R.aFrame(g, x + 1.4, -0.2, Math.PI, c);
    });

    /* ── 라운지 두 번째 자리 ── 소파 하나로는 "쉬는 곳" 이 안 됩니다 */
    R.roundRug(g, -8.8, 6.2, 0xB9DDE5, 0xEAF6F8, 2.1);
    R.beanbag(g, -9.9, 5.6, .6, 0x9B7BD4);
    R.beanbag(g, -7.7, 6.9, -2.2, 0x63C47C);
    R.sideTable(g, -8.8, 6.2);
    R.floorLamp(g, -10.2, 8.0);
    R.plantTall(g, -4.4, 6.4, 1.0);

    /* 오른쪽 벽에서 실내를 바라보도록 정면(+z)을 -x 방향으로 돌립니다. */
    R.vending(g, 12.0, -4.8, -Math.PI / 2);
    R.vending(g, 12.0, -2.9, -Math.PI / 2);
    R.cooler(g, -12.1, 4.7, Math.PI / 2);
    R.coffee(g, -12.0, 1.06, 6.4, Math.PI / 2);
    R.lockers(g, 12.0, 5.6, -Math.PI / 2, 3, 0x9BC4B4);
    R.aFrame(g, 10.8, 7.0, -1.1, 0x2DD4BF);
    R.clock(g, 11.2, 3.7, -8.82);
    R.bin(g, -3.8, 7.5); R.bin(g, 3.8, 7.5, 0xE8935A);
    [-8.2, 0, 8.2].forEach((x) => R.striplight(g, x, .4, 4.68, 3.6));
    [-7.8, 7.8].forEach((x) => R.pendant(g, x, 5.6, 4.12, 0xE8C08A));
    R.rug(g, -7.8, 2.8, 5.0, 3.6, 0xB9DDE5, 0xEAF6F8);
    /* 오른쪽 벽 화분(11.8, 0)은 뺐습니다 — 식탁이 늘면서 화분·식탁·벽
       사이에 사람이 못 들어가는 주머니가 하나 생겼습니다(닿는비율 99.8%). */
    R.plant(g, 12.2, 7.5, 1.15); R.plant(g, -12.2, 7.5, 1.0);

  },

  /* ══ ⑤ 미니게임관 ══ 20×14. 오락기는 벽으로, 가운데는 비웁니다. */
  arcade(g) {
    R.doormat(g, 0, 6.2, 0x6E5A9E);
    R.exitSign(g, 0, 6.72, 0x9B7BD4);

    R.shell(g, 20, 14, 4.6, { floorA: 0xDDD8EC, floorB: 0xC7C0DE, wall: 0xF3EFFA, under: 0xA69CBE });
    const cols = [0x5FAFE0, 0x55C6AE, 0x9B7BD4];
    const themes = ['runner', 'memory', 'match3'];
    /* 2048을 삭제하고 남은 게임 셋을 뒤벽 한 줄에 같은 간격으로 정렬합니다. 각 기계 앞 원형
       발판 색이 기능 구역과 같아 어느 기계를 누르는지 바로 보입니다. */
    [-6.4, 0, 6.4].forEach((x, i) => {
      R.cabinet(g, x, -6.4, 0, cols[i], themes[i]);
      R.neon(g, '', x, 3.1, -6.92, 0, cols[i], 1.8);
      R.rug(g, x, -5.15, 3.2, 2.35, cols[i], i === 0 ? 0xE1F2FB : i === 1 ? 0xDDF4EE : 0xECE8FA);
      cyl(g, .34, .3, .12, 14, M(0x2DD4BF, .6), x, .62, -5.0);
      [[-1,-1],[1,-1],[-1,1],[1,1]].forEach(([sx, sz]) =>
        cyl(g, .04, .05, .56, 8, M(IN.metal, .45), x + sx * .2, .3, -5.0 + sz * .2));
    });
    /* 인형 대신 희귀 알·티켓·선물 상자가 보이는 이벤트 기계 한 대. */
    R.claw(g, -8.3, 1.2, .20, 0xFFD16B);
    R.prizeShelf(g, -9.2, 3.8, Math.PI / 2);
    /* 에어하키 · 인생네컷 — 오른쪽 */
    R.airHockey(g, 6.8, 1.0, .08);
    R.photoBooth(g, 7.4, 4.6, .7, 0xFF7FA8);
    /* 네 번째 실제 게임 — 동물 합치기. 장식용 리듬 발판을 치우고 전용
       기계·클레이 구슬 화면·대기 발판을 출입구 왼쪽에 독립 배치합니다. */
    R.cabinet(g, -5.8, 4.15, Math.PI, 0xE98D79, 'merge');
    R.rug(g, -5.8, 2.85, 3.4, 2.5, 0xE98D79, 0xFBE7E1);
    R.neon(g, '', -5.8, 3.1, 6.92, Math.PI, 0xE98D79, 2.0);
    /* 교환대 */
    R.counter(g, -3.6, 6.1, 0, 3.0, 0x4E4068);
    R.counterTop(g, -3.6, 1.1, 6.4);
    R.stanchion(g, -5.4, 5.2, -1.8, 5.2);
    R.neon(g, '', -9.6, 3.2, 0.4, Math.PI / 2, 0x2DD4BF, 3.0);
    R.bin(g, 2.9, 6.4, 0x3A3050);

    /* ── 기다리는 자리 ── 오락실인데 앉을 곳이 하나도 없었습니다.
       기계는 전부 벽에 붙어 있고 가운데를 덮은 비율이 2% 라, 방이
       기계 사이의 빈 복도로 읽혔습니다. 세로 통로(x -2.4~2.4)와
       가로 통로(z 0.6~2.6)를 비켜 좌우 띠에 둡니다. */
    [[-4.4, -1.6, 0], [4.4, -1.6, Math.PI]].forEach(([x, z, ry]) => {
      R.bench(g, x, z, ry, 2.6, 0x4E4068);
      R.bin(g, x + (x < 0 ? -1.7 : 1.7), z - .9, 0x3A3050);
    });
    R.vending(g, 9.4, -1.8, -Math.PI / 2);
    R.plantTall(g, -9.4, -1.8, .95);
    /* 순위판 — 게임을 하고 나면 볼 것이 있어야 다시 합니다 */
    R.board(g, 4.4, 2.9, -6.92, 2.4, 1.5);

    [-6.0, 0, 6.0].forEach((x) => R.pendant(g, x, -1.0, 4.02, 0xFF7FA8));
    R.rug(g, 0, -4.8, 18.0, 3.4, 0x3E3358, 0x6E5A9E);
    R.plant(g, 9.4, 6.2, 1.05); R.plant(g, -9.4, 6.2, 1.0);

  },

  /* ══ ⑥ 동아리 상점 ══ 24×17. 왼쪽 옷 · 오른쪽 알 · 앞쪽 가구. */
  shop(g) {
    R.doormat(g, 0, 7.5, 0xC4553F);
    R.exitSign(g, 0, 8.02, 0xE8695A);

    R.shell(g, 24, 17, 5.0, { floorA: 0xE2EAEC, floorB: 0xCBDADF, wall: 0xF8FBFC, under: 0x8FAAB4 });
    R.window3(g, 7.6, 2.9, 17, 2.4, 2.2);
    R.window3(g, -5.6, 2.9, 17, 2.2, 2.2);

    /* ─ 옷 구역(왼쪽 뒤) ─ 구매는 옷걸이 앞 한 곳에서만 엽니다. */
    R.rack(g, -10.0, -5.8, 0);
    R.rack(g, -10.0, -3.2, 0);
    R.rack(g, -6.8, -5.8, 0);
    R.mannequin(g, -6.8, -3.2, .5, 0xE8695A, 0x3E5C82);
    R.shoeShelf(g, -11.2, -.5, Math.PI / 2);
    R.hatWall(g, -8.2, 2.5, -8.42, 0, 5);

    /* ─ 알 구역(오른쪽) ─
       팝업에서 파는 여덟 종과 실제 선반 수도 같습니다. */
    const eggDisplay = [
      [6.2, -6.0, 0x78C98A], [7.7, -6.0, 0xE7AD45],
      [9.2, -6.0, 0x4F6078], [10.7, -6.0, 0xDCA76E],
      [6.2, -3.5, 0x72D62D], [7.7, -3.5, 0xC99972],
      [9.2, -3.5, 0xD8C0A6], [10.7, -3.5, 0xDDE4EA],
    ];
    eggDisplay.forEach(([x, z, c]) => R.eggStand(g, x, z, c));
    R.wallShelf(g, 11.2, 2.7, -1.0, -Math.PI / 2, 2.0);
    /* 알 여덟 개가 상품 진열 자체라 계산대와 별도 게임 탁자는 두지 않습니다. */

    /* ─ 가구 구역(출입문 왼쪽 앞) ─
       방을 통째로 복사한 듯 흩어져 있던 소파·책상 둘을 걷고, 왼쪽 벽에
       붙은 한 개의 쇼룸으로 묶습니다. 중앙 문길(x -2~2)과 알 구역은
       완전히 비워 두므로 진열과 출입이 겹치지 않습니다. */
    R.rug(g, -8.4, 4.1, 7.0, 4.7, 0x725B9A, 0xE6DDF2);
    R.sofa(g, -10.35, 4.15, Math.PI / 2, 2.7, 0x8CAFC8);
    R.lowTable(g, -8.35, 4.15, 0, 1.5, .86);
    R.chair(g, -7.0, 5.55, -2.5, 0xE8935A);
    R.floorLamp(g, -10.65, 6.35);
    R.shelf(g, -11.15, 1.35, Math.PI / 2, 1.8, 2.1);
    R.displayTable(g, -6.55, 2.05, -.08, 1.8, 'furn');

    /* ─ 계산대 ─ 상점인데 계산대가 없었습니다. 세 구역을 다 돌고
       나오는 길목(출입문 오른쪽 앞)에 둡니다. 세로 문길(x -2.6~2.6)
       과 가로 통로(z 0.4~2.5)는 그대로 비웁니다. */
    /* 계산대는 **벽을 등지고** 서야 합니다. 방 한가운데 두면 주인 없는
       책상으로 보이고, 뒤 선반을 걸 벽도 없습니다. 오른쪽 벽에 붙이되
       가로 통로(z 0.4~2.5)와 A자 간판(10.4, 7.0)은 비켜 갑니다. */
    R.counter(g, 10.5, 4.6, -Math.PI / 2, 3.0, IN.woodDark);
    R.counterTop(g, 10.3, 1.1, 4.6);
    R.chair(g, 11.3, 4.6, -Math.PI / 2, 0xE8935A);
    box(g, .06, .5, .78, .06, M(0xDCEAF5, .5), 10.06, 1.30, 4.0);
    box(g, .07, .22, .22, .05, M(0x2DD4BF, .5), 10.06, 1.34, 5.3);
    R.wallShelf(g, 11.72, 2.6, 4.6, -Math.PI / 2, 1.8);

    /* ─ 옷 구역 마무리 ─ 입어 보지 못하는 옷가게는 창고입니다 */
    R.standMirror(g, -4.6, -7.2, .5);
    R.curtain(g, -11.6, 2.1, -7.4, Math.PI / 2, 1.3, 2.1, 0xB05248);

    /* ─ 가운데 신상 진열 ─ 세로 문길 바로 옆 폭 3 짜리 띠가 비어
       있어서, 문에서 들어오면 양쪽 구역 사이가 복도처럼 보였습니다. */
    R.displayTable(g, 4.2, -1.6, 0, 2.0, 'cloth');
    R.displayTable(g, -4.2, -1.6, 0, 2.0, 'furn');

    R.aFrame(g, 10.4, 7.0, -1.2, 0xE8935A);
    R.banner(g, -11.72, 3.9, -2.0, Math.PI / 2, 3.2, .95, 0xE8935A);
    R.clock(g, 10.2, 3.8, -8.42);
    R.poster(g, 2.8, 3.3, -8.42, 0, 1.1, 1.4, 0x9B7BD4);
    R.bin(g, 3.8, 7.6);
    [-7.5, 0, 7.5].forEach((x) => { R.pendant(g, x, -4.6, 4.42, 0xF2C14E); R.pendant(g, x, 5.1, 4.42, 0xF2C14E); });
    /* 세 구역 바닥색도 팝업 포인트색과 맞춥니다. */
    R.rug(g, -8.2, -3.1, 7.2, 9.0, 0xB05248, 0xF6D5CF);
    R.rug(g,  8.2, -4.4, 7.0, 7.0, 0x4F7E8D, 0xDCECEF);
    /* 가구 러그는 위 쇼룸 범위에서만 깔았습니다. 문 앞을 가로지르던
       18.8m 러그는 삭제해 세 구역의 경계를 눈으로도 분리합니다. */
    R.plant(g, 11.2, 7.4, 1.15); R.plant(g, -11.2, 7.4, 1.0);

  },
};

/* 방마다 이름 — HUD 에 띄웁니다 */
export const ROOM_NAME = {
  library: ['도서관', '백색소음 · 오래 앉는 자리'],
  mainhall: ['본관', '강의실 · 대중음악'],
  dorm: ['기숙사', '내 방 · 1인실'],
  union: ['학생회관', '볼일 보는 곳'],
  arcade: ['미니게임관', '3분만 놀고 가는 곳'],
  shop: ['동아리 상점', '옷 · 가구 · 알'],
};

/* 놓는 가구 — 상점 FURN 목록과 1:1. 유령(미리 보기)과 실물이 같은 코드를 씁니다 */
export function decorItem(g, d) {
  const p = new THREE.Group(); p.position.set(d.x, 0, d.z); p.rotation.y = d.ry || 0; g.add(p);
  const id = d.id;
  if (id === 'plant') R.plant(p, 0, 0, 1.0);
  else if (id === 'rug2') R.rug(p, 0, 0, 2.2, 1.6, 0x9B7BD4, 0xF2ECF6);
  else if (id === 'books2') { R.books(p, -.1, .0, 0, 3); R.books(p, .16, .0, .1, 2); }
  else if (id === 'guitar2') R.guitar(p, 0, 0, .4);
  else if (id === 'lamp2') {
    cyl(p, .16, .2, .05, 12, M(0x3A4150, .5), 0, .03, 0);
    cyl(p, .025, .03, 1.1, 8, M(0x3A4150, .5), 0, .6, 0);
    const sh2 = new THREE.Mesh(new THREE.ConeGeometry(.22, .26, 14, 1, true), M(0xF2C14E, .55));
    sh2.position.y = 1.24; sh2.rotation.x = Math.PI; p.add(sh2);
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(.07, 10, 8),
      new THREE.MeshStandardMaterial({ color: 0xFFF2C8, emissive: 0xFFE9A8, emissiveIntensity: .9 }));
    bulb.position.y = 1.18; p.add(bulb);
  } else if (id === 'bear') {
    const br = M(0xC49A6C, .8), brD = M(0xA8804F, .8);
    const e2 = (r, x, y, z, sx = 1, sy = 1, sz = 1) => {
      const m2 = new THREE.Mesh(new THREE.SphereGeometry(r, 14, 10), br);
      m2.position.set(x, y, z); m2.scale.set(sx, sy, sz); m2.castShadow = true; p.add(m2); return m2;
    };
    e2(.22, 0, .24, 0, 1, 1.05, .9);                       // 몸
    e2(.17, 0, .56, .02);                                   // 머리
    e2(.06, -.12, .68, 0); e2(.06, .12, .68, 0);            // 귀
    e2(.08, -.2, .3, .06); e2(.08, .2, .3, .06);            // 팔
    e2(.09, -.11, .08, .1); e2(.09, .11, .08, .1);          // 다리
    { const mz = new THREE.Mesh(new THREE.SphereGeometry(.07, 10, 8), brD);
      mz.position.set(0, .53, .16); mz.scale.set(1, .8, .7); p.add(mz); }
  }
  /* 여섯 말고는 room.js 의 표에 물어봅니다. 2D 판 기숙사에는 놓을 수 있는
     물건이 스무 가지쯤 있었는데 여기는 여섯이라, 방을 꾸며도 다 같은
     방이 됐습니다. 새 것을 이 if 사슬에 계속 붙이면 이 함수가 천 줄이
     되므로, 짓는 일은 저쪽에 두고 여기서는 넘기기만 합니다. */
  else if (R.buildFurn) R.buildFurn(p, id);
  return p;
};
